def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find monochrome runs on the four borders.
    runs = []
    for side in ("top", "bottom", "left", "right"):
        length = w if side in ("top", "bottom") else h
        fixed = 0 if side in ("top", "left") else (h - 1 if side == "bottom" else w - 1)
        i = 0
        while i < length:
            r, c = ((fixed, i) if side in ("top", "bottom") else (i, fixed))
            color = grid[r][c]
            if color == background:
                i += 1
                continue
            j = i + 1
            while j < length:
                rr, cc = ((fixed, j) if side in ("top", "bottom") else (j, fixed))
                if grid[rr][cc] != color:
                    break
                j += 1
            if j - i >= 2:
                runs.append((side, i, j, color))
            i = j

    if not runs:
        return [row[:] for row in grid]
    bar_color = max({run[3] for run in runs}, key=lambda color: counts[color])
    other_colors = [color for color in counts if color not in (background, bar_color)]
    if not other_colors:
        return [row[:] for row in grid]
    ray_color = max(other_colors, key=lambda color: counts[color])
    out = [row[:] for row in grid]

    # A marker's position within one edge run selects the same offset in
    # every matching edge run. The rays extend inward until they meet a marker.
    for orientation in ("horizontal", "vertical"):
        matching = [run for run in runs
                    if run[3] == bar_color and
                    ((orientation == "horizontal" and run[0] in ("top", "bottom")) or
                     (orientation == "vertical" and run[0] in ("left", "right")))]
        if not matching:
            continue
        offsets = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != ray_color:
                    continue
                position = c if orientation == "horizontal" else r
                for side, start, end, _ in matching:
                    if start <= position < end:
                        offsets.add(position - start)
        for side, start, end, _ in matching:
            for offset in offsets:
                position = start + offset
                if position >= end:
                    continue
                if orientation == "horizontal":
                    r = 1 if side == "top" else h - 2
                    step = 1 if side == "top" else -1
                    while 0 <= r < h:
                        if grid[r][position] == ray_color:
                            out[r][position] = 4
                            break
                        if grid[r][position] != background:
                            break
                        out[r][position] = ray_color
                        r += step
                else:
                    c = 1 if side == "left" else w - 2
                    step = 1 if side == "left" else -1
                    while 0 <= c < w:
                        if grid[position][c] == ray_color:
                            out[position][c] = 4
                            break
                        if grid[position][c] != background:
                            break
                        out[position][c] = ray_color
                        c += step
    return out
